-- =============================================================================
-- 社内承認の依頼の通知（*_review_request_notify.sql）の検証ハーネス用: 本 migration の前からあるデータ
-- run_review_request_notify.sh が、本 migration の手前までの migrations のあと・本 migration の前に流す。
--
-- 組織 O1・プロジェクト S1（通常）・S2（アーカイブ済み）。人物:
--   req   依頼する人（O1 owner・S1 admin）
--   rv1   承認を頼まれる人（O1 member・S1 editor）
--   rv2   承認を頼まれる人（通知はすでに届いていて、読んである）
--   rv3   承認済みの人（O1 member・S1 editor）
--   vw    閲覧者（O1 member・S1 viewer）
--   cl    相手先（O1 client・S1 client）… 07-05 より前は承認者に指定できた
--   gone  プロジェクトから外された人（O1 member・S1 の役割なし）
-- データ（承認者の行は、本番の一括作成と同じく RPC を通さずに直接入れる）:
--   T1/R1  依頼中（open）: rv1=pending（通知なし・依頼された時刻 2026-09-10 09:21:38Z）/ rv3=approved /
--          req=pending（依頼した本人が承認者にも入っている）/ cl=pending / gone=pending
--   T2/R2  取り消し済み（cancelled）: rv1=pending（通知なし）
--   T3/R3  依頼中（open）: rv2=pending（通知あり・既読）
--   T4     承認の依頼がまだ無いタスク（rpc_review_open の確認用）
--   T5/R5  アーカイブ済みのプロジェクト S2 の依頼中（open）: rv1=pending（通知なし）
-- =============================================================================

on conflict (id) do nothing;

on conflict (id) do update set display_name = excluded.display_name;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict do nothing;

on conflict do nothing;

